#define MAX_STEPS 250
#define MAX_DIST 40.0
#define SURF_DIST 0.001

#define GROUND 0
#define CUBE_FRONT 1
#define CUBE_REAR 2

struct RaymarchHit {
	int type;
    float dist;
};


// -------------------------------------------------------------------------
//  Utility functions
// -------------------------------------------------------------------------
mat2 rotate(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

float smin(float a, float b, float k) {
	float h = clamp( 0.5 + 0.5*(b-a)/k, 0.0, 1.0 );
	return mix( b, a, h ) - k*h*(1.0-h);
}

float smax(float a, float b, float k) {
    return smin(a, b, -k);
}

float hash21(vec2 p) {
    p = fract(p*vec2(123.34,234.34));
    p += dot(p, p+23.43);
    return fract(p.x*p.y);
}

// Distance-based glow function
// https://www.shadertoy.com/view/3s3GDn
float getGlow(float dist, float radius, float intensity){
	return pow(radius / max(dist, 0.00006), intensity);	
}

// Calculates the distance along the ray to the point (pp) on the plane
vec3 rayPlane(vec3 ro, vec3 rd, vec3 pp, vec3 normal) {

    // Clamp the result to zero to ensure the intersection is in front of the ray origin
    float t = max(0.0, dot(pp-ro, normal) / dot(rd, normal));
    return ro + rd*t;
}

vec3 lookAt(vec2 uv, vec3 ro, vec3 target, float zoom) {
    vec3 forward = normalize(target-ro);
    vec3 r = normalize(cross(vec3(0,1,0), forward));
    vec3 u = cross(forward,r);
    vec3 c = ro+forward*zoom;
    vec3 i = c + uv.x*r + uv.y*u;
    vec3 rd = normalize(i-ro);
    return rd;
}

// -------------------------------------------------------------------------
//  Generates a glitter pattern
// -------------------------------------------------------------------------
float glitterLayer(vec2 p, float offset) {
    float t = iTime*2.+offset;

    vec2 id = floor(p);
    vec2 gv = fract(p)-0.5;    

    float dist = length(gv);    
    float sparkleSize = 0.23;
    float sparkle = smoothstep(sparkleSize, 0.0, dist);

    // Pow creates a quick on-off effect by reducing values near zero, emphasizing the "off" state
    // Modulating the phase shift with a random value causes the sparkles to flicker more randomly
    float n = hash21(id);
    const float tau = 6.2832;
    sparkle *= pow(sin(t+n*tau) * 0.5 + 0.5, 7.);

    return sparkle;
}

// -------------------------------------------------------------------------
//  Signed distance functions
// -------------------------------------------------------------------------
float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdCube(vec3 p, vec3 size) {
    vec3 d = abs(p) - size;
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Computes the signed distance to a cube with sine wave deformation
float sdWavyCube(vec3 p, vec3 size) {

    float anim = iTime;
    const float frequency = 5.0;
    p.x += sin(p.y * frequency + anim) * 0.1;
    p.y += sin(p.z * frequency + anim) * 0.1;
    p.z += sin(p.x * frequency + anim) * 0.1;

    vec3 d = abs(p) - size;
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Computes the signed distance to a wireframe cube with sine wave deformation
float sdWavyCubeWireframe(vec3 p) {

    const float thickness = 0.2;

    const float w = 1.1;
    const float w2 = 1.5;
    const float w3 = 1.15;

    float cube1 = sdWavyCube(p, vec3(w3));
    float cube2 = sdWavyCube(p, vec3(w, w, w2 ));
    float cube3 = sdWavyCube(p, vec3(w, w2, w));    
    float cube4 = sdWavyCube(p, vec3(w2, w, w));

    cube2 = abs(cube2) - thickness;
    cube3 = abs(cube3) - thickness;
    cube4 = abs(cube4) - thickness;

    float cube = smax(smax(smax(cube1, cube2, thickness), cube3, thickness), cube4, thickness);

    return cube;
}

// Returns the wireframe representation of a cube sliced along a plane parallel 
// to the camera's view.
float sdWavyCubeWireframeSliced(vec3 p, vec3 ro, bool isFrontHalf) {

    float cube = sdWavyCubeWireframe(p);

    // Compute the direction from the camera to the cube's center
    vec3 cubeCenter = vec3(0);
    vec3 rd = normalize(cubeCenter - ro);

    // Compute the distance to the slicing plane, parallel to the camera's view direction
    float planeDist = dot(p - cubeCenter, rd);

    // Use the max function to keep only one half of the cube  
    cube = max(cube, isFrontHalf ? planeDist : -planeDist);
    return cube;
}

// -------------------------------------------------------------------------
//  Standard raymarching routines and glow rendering
// -------------------------------------------------------------------------
RaymarchHit getDist(vec3 p, vec3 rd) {

    float cubeFront = sdWavyCubeWireframeSliced(p, rd, true);    
    float cubeRear = sdWavyCubeWireframeSliced(p, rd, false);
    float ground = p.y+1.8;

    if (ground < cubeFront && ground < cubeRear) {
        return RaymarchHit(GROUND, ground);
    }

    if (cubeFront < cubeRear) {
        return RaymarchHit(CUBE_FRONT, cubeFront);
    }

    return RaymarchHit(CUBE_REAR, cubeRear);
}

vec3 getNormal(vec3 p, vec3 rd) {
	float d = getDist(p, rd).dist;
    vec2 e = vec2(SURF_DIST, 0);

    vec3 n = d - vec3(
        getDist(p-e.xyy, rd).dist,
        getDist(p-e.yxy, rd).dist,
        getDist(p-e.yyx, rd).dist);

    return normalize(n);
}

// Calculates the glow from the center light. The glow is computed at each step
// and accumulated along the entire view ray
float rayMarchGlow(vec3 ro, vec3 rd, float innerLightSize) {

    float t = 0.0;
    float glow = 0.0;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;

        float sphereDist = sdSphere(p, innerLightSize);

        // Reduce the step size to make the result smoother
        t += sphereDist/5.;

        if (sphereDist < 2.85 ) {
            glow += getGlow(sphereDist, .0018, .90);
        } 

        if (sphereDist < SURF_DIST || abs(t) > MAX_DIST) {
            break;            
        }
    }
    return glow;
}

// Standard raymarching routine
RaymarchHit rayMarch(vec3 ro, vec3 rd) {

   float t = 0.0;
   RaymarchHit obj = RaymarchHit(-1, -1.);

   for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;
        obj = getDist(p, ro);

        float dist = obj.dist;
        t += dist;

        if (dist < SURF_DIST || abs(t) > MAX_DIST) {            
            return RaymarchHit(obj.type, t);
        }
    }
    return obj;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 8.0, 6.0);

    vec2 m = iMouse.xy / iResolution.xy;

    // Rotate camera based on the mouse movement
    if (m.y > 0.0) {
        ro.yz *= rotate(-m.y * 3.14 + 2.0);
        ro.xz *= rotate(-m.x * 6.2831);
    }

    // Prevent the camera from going below the floor
    ro.y = max(ro.y, -0.3);

    vec3 rd = lookAt(uv, ro, vec3(0,0,0), 1.2);

    // Inner light
    float innerLightSize = 0.05;

    float t = iTime;
    float k = sin(t) + sin(t*5.0)*0.5 + sin(t*17.0)*0.25 + sin(t*37.0)*0.2;
    float pulse = 0.1+k*0.02;
    innerLightSize += pulse;

    // Add glow to the inner light
    float glow = rayMarchGlow(ro, rd, innerLightSize); 
    vec3 glowColor = vec3(1., 0.15, 0.2) * glow;
    vec3 col = glowColor;    

    RaymarchHit result = rayMarch(ro, rd);

    if (result.dist < MAX_DIST) {

        vec3 p = ro + rd * result.dist;
        vec3 normal = getNormal(p, rd);

        // Makes the light to look to come from inside the cube
        vec3 lightDir = -normalize(p);

        if (result.type == GROUND) {
            float f = mod( floor(.3*p.x) + floor(.3*p.z), 2.0);
            col = f * vec3(1);           

            // Add shadows                          
            // Use distance to center to limit the length of the shadows
            float centerDist = length(p);  
            float s = sdWavyCubeWireframe(-lightDir) - centerDist*.005;

            float w = 0.35;
            float shadow = smoothstep(w+0.2, w, s);

            // Add glitter
            vec2 st = p.xz;    

            // Adjust sparkle based on camera angle
            float offset = dot(rd, vec3(1));

            // Add multiple layers with varying size of sparkles
            float glitter = glitterLayer(st*10., offset);
            glitter += glitterLayer(st*16., offset);
            glitter += glitterLayer(st*25., offset);

            glitter = pow(glitter*1.4, 10.);
            glitter /= centerDist*3.;

            // Prevent glitter from appearing within the shadow              
            col += glitter * (shadow/.8);

            col *= shadow;

            // Make the edge of the plane darker
            col /= centerDist * centerDist;

            col += glowColor;

        } else if (result.type == CUBE_FRONT || result.type == CUBE_REAR) {

            float diff = dot(normal, lightDir)* 0.5 + 0.5;
            col = vec3(diff);

            // Subsurface Scattering: add red to the cube front        
            vec3 albedo = vec3(1., 0., 0.); // Material color
            float scatCoeff = 1.2;          // Amount of scattering
            float absCoeff = 0.2;           // Amount of absorption
            float thickness = 0.2;          // Thickness of the material

            vec3 scatter = albedo * scatCoeff * exp(-absCoeff * thickness);

            float camDist = length(ro);
            scatter *= smoothstep(1., .75, result.dist/camDist);

            col += scatter;

            if (result.type == CUBE_REAR) {
                col += glowColor;
            }
        }
    }

    // Add volumetric starburst
    float centerDist = dot(uv, uv);

    // Determine the intersection point of a plane that is located inside the cube
    // and always facing the camera. 
    vec3 planePoint = rayPlane(ro, rd, vec3(0.0), normalize(ro));

    // Determine if the point is shaded by the cube. This works because the cube's size 
    // is chosen such that the distance to the wireframe is approximately one.
    float shade = sdWavyCubeWireframe(normalize(planePoint));

    // If the intersection point is within a shaded region, apply colorization.
    float starburst = max(0.1, shade-0.2);
    starburst *= 0.20*smoothstep(1.2, 0., centerDist);

    // Add additional distortion to the brightness of the starburst
    pulse = 1.+k*0.2;        
    col += starburst * pulse;

    // Add vignette
    uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    col *= 1.-dot(uv,uv);

    // Tone mapping makes the glow a little nicer
    col = 1.0 - exp(-col);

    // Gamma correction
    col = pow(col, vec3(.4545));

    fragColor = vec4(col, 1.0);
}
